<script setup lang="ts">
import { ref, computed, watch, onMounted, onBeforeUnmount } from 'vue'
import { ArrowUpRight, Play, Pause, LoaderCircle, RefreshCw, ExternalLink, Copy, Check, Wallet, ShieldCheck } from '@lucide/vue'
import { account, wrongNetwork, NETWORK, marketSnapshot, recentTrades, tradeQuote, executeTrade, formatUnits, errorText, graduateSound, soundMetadata, claimFees, distributeFees, releaseVested, transferRecipient, toggleBuyback } from '../chain-v2'
import type { MarketSnapshot, TradeRecord, SoundMetadata, TradeQuote } from '../chain-v2'
const props = defineProps<{ address: string; name: string; symbol: string; creator: string; art: string; playing: boolean }>()
const emit = defineEmits<{ play: []; connect: []; traded: []; busy: [value: boolean] }>()
const state = ref<MarketSnapshot | null>(null), metadata = ref<SoundMetadata | null>(null), records = ref<TradeRecord[]>([])
const loading = ref(true), busy = ref(false), quoting = ref(false), dataError = ref(''), activityError = ref(''), message = ref(''), txHash = ref(''), copied = ref('')
const side = ref<'buy'|'sell'>('buy'), amount = ref('0.001'), quoted = ref<TradeQuote | null>(null), quoteError = ref(''), newRecipient = ref('')
const now = ref(Math.floor(Date.now()/1000))
let epoch = 0, alive = true, quoteTimer: ReturnType<typeof setTimeout>, copyTimer: ReturnType<typeof setTimeout>, clockTimer: ReturnType<typeof setInterval>
const explorer = NETWORK.blockExplorerUrls[0]
const shareUrl = `${location.origin}${location.pathname}#sound=${props.address}`
const short = (value: string) => `${value.slice(0,6)}…${value.slice(-4)}`
const compact = (value: string | number) => Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:2}).format(Number(value))
const number = (value: string | number) => !Number(value) ? '0' : Math.abs(Number(value)) < 0.00001 ? Number(value).toExponential(3) : Number(value).toLocaleString('en',{maximumSignificantDigits:6})
const currency = computed(()=>state.value?.quote.symbol || 'ETH')
const creatorConnected = computed(()=>!!account.value && state.value?.recipient.toLowerCase() === account.value.toLowerCase())
const paused = computed(()=>!!state.value && (state.value.phase === 1 || state.value.phase === 3 || state.value.ready))
const pool = computed(()=>state.value?.phase === 2)
const baseFee = computed(()=>(pool.value ? state.value?.hookFeeBps : state.value?.baseFeeBps) ?? 100)
const phaseLabel = computed(()=>['LIVE CURVE','AWAITING POOL','UNISWAP V4','RESCUED MARKET'][state.value?.phase || 0])
const launchWindow = computed(()=>!!state.value && state.value.phase === 0 && now.value < state.value.snipeUntil)
const graphPoint = (fraction: number) => {
  if (!state.value) return {x:20,y:145}
  const s = state.value, total = Number(s.supply), remaining = total - (total - Number(s.reserved))*fraction
  const price = Number(s.phantom)*total/(remaining*remaining), y = 145 - (price-Number(s.basePrice))/(Number(s.terminalPrice)-Number(s.basePrice))*110
  return {x:20+510*fraction,y}
}
const curvePath = computed(()=>Array.from({length:61},(_,i)=>{const p=graphPoint(i/60);return `${i?'L':'M'}${p.x},${p.y}`}).join(' '))
const currentPoint = computed(()=>graphPoint((state.value?.progress || 0)/100))
const allocation = computed(()=>state.value ? Number(state.value.supply)-Number(state.value.reserved) : 0)
watch(busy,value=>emit('busy',value))
async function copy(value:string,label:string) { try { await navigator.clipboard.writeText(value);copied.value=label;clearTimeout(copyTimer);copyTimer=setTimeout(()=>copied.value='',2000) } catch {message.value=value} }
async function refresh() {
  loading.value=true;dataError.value='';activityError.value=''
  try {
    const [s,m] = await Promise.all([marketSnapshot(props.address),soundMetadata(props.address)])
    if (!alive) return
    state.value=s;metadata.value=m
    try { const r=await recentTrades(props.address,s.block);if(alive)records.value=r } catch(error){activityError.value=errorText(error)}
  } catch(error){dataError.value=errorText(error)} finally {loading.value=false}
}
async function updateQuote() {
  const request=++epoch;quoted.value=null;quoteError.value='';quoting.value=false
  if (!state.value || paused.value) return
  quoting.value=true
  try {const q=await tradeQuote(props.address,side.value,amount.value);if(request===epoch&&alive){if(q.phase!==state.value?.phase){await refresh();quoteError.value='This market changed phase. Refresh the quote to review its new trading terms.'}else quoted.value=q}}
  catch(error){if(request===epoch&&alive)quoteError.value=errorText(error)}
  finally {if(request===epoch&&alive)quoting.value=false}
}
watch([amount,side],()=>{++epoch;quoted.value=null;clearTimeout(quoteTimer);quoteTimer=setTimeout(updateQuote,300)})
watch(side,value=>amount.value=value==='buy'?(currency.value==='ETH'?'0.001':'1'):'10000')
watch(account,()=>{++epoch;quoted.value=null;refresh().then(updateQuote)})
const pending=(hash:string)=>{txHash.value=hash;message.value='Transaction submitted. Waiting for confirmation…'}
async function action(task:()=>Promise<void>,success:string) {
  if(busy.value)return
  busy.value=true;message.value='';txHash.value=''
  try {await task();await refresh();await updateQuote();message.value=success;emit('traded')}
  catch(error){message.value=errorText(error);await refresh();await updateQuote()}
  finally {busy.value=false}
}
function execute() {const q=quoted.value;if(q)action(()=>executeTrade(q,pending),'Trade confirmed. Tokens, sale proceeds and any unused payment go directly to your wallet.')}
onMounted(async()=>{await refresh();if(currency.value!=='ETH'&&side.value==='buy'&&amount.value==='0.001')amount.value='1';await updateQuote();clockTimer=setInterval(()=>{now.value=Math.floor(Date.now()/1000);if(launchWindow.value&&!busy.value&&!quoting.value)updateQuote()},1500)})
onBeforeUnmount(()=>{alive=false;++epoch;clearTimeout(quoteTimer);clearTimeout(copyTimer);clearInterval(clockTimer);emit('busy',false)})
</script>

<template>
  <section class="ab-market">
    <div class="ab-market-kicker"><span><i></i>{{ phaseLabel }} · TESTNET</span><button class="ab-text-btn" :disabled="loading||busy" @click="refresh().then(updateQuote)"><RefreshCw :size="12" :class="{'is-spin':loading}"/>Refresh</button></div>
    <header class="ab-market-head"><img :src="metadata?.cover||art" :alt="`${name} cover`"/><div class="ab-market-id"><span class="ab-market-sym">${{symbol}}</span><h2>{{name}}</h2><a :href="`${explorer}/address/${creator}`" target="_blank" rel="noopener">Created by {{short(creator)}}<ArrowUpRight :size="11"/></a></div><button class="ab-market-play" :aria-label="playing?'Pause sound':'Play sound'" @click="emit('play')"><Pause v-if="playing" :size="21" fill="currentColor"/><Play v-else :size="21" fill="currentColor"/></button></header>
    <div class="ab-market-links"><a :href="`${explorer}/address/${address}`" target="_blank" rel="noopener">{{short(address)}}<ExternalLink :size="11"/></a><button @click="copy(address,'address')"><Check v-if="copied==='address'" :size="12"/><Copy v-else :size="12"/>Address</button><button @click="copy(shareUrl,'link')">{{copied==='link'?'Copied':'Share sound'}}<ArrowUpRight :size="12"/></button></div>
    <p v-if="dataError" class="ab-warn ab-market-error" role="status">{{dataError}}</p>
    <div v-if="metadata" class="ab-market-story"><p v-if="metadata.description">{{metadata.description}}</p><div class="ab-market-socials"><template v-for="(url,channel) in metadata.socials" :key="channel"><a v-if="url" :href="url" target="_blank" rel="noopener noreferrer nofollow">{{channel}}<ArrowUpRight :size="11"/></a></template></div></div>
    <div class="ab-market-cols">
      <div class="ab-market-main">
        <div class="ab-market-stats"><div><span>{{pool?'MARKET PHASE':'PRICE / TOKEN'}}</span><strong>{{pool?'Pool trading':state?.price?number(state.price):'—'}} <small v-if="!pool">{{currency}}</small></strong></div><div><span>{{state?.phase?'CURVE TARGET':'REAL CURVE RESERVE'}}</span><strong>{{state?number(state.phase?state.target:state.reserve):'—'}} <small>{{currency}}</small></strong></div><div><span>FIXED TOKEN SUPPLY</span><strong>{{state?compact(state.supply):'—'}}</strong></div><div><span>ADDITIONAL CREATOR TAX</span><strong>{{(state?.taxBps||0)/100}}<small>%</small></strong></div></div>
        <div class="ab-market-chart"><div class="ab-chart-tabs"><span class="is-on">Virtual reserve curve</span><span>CONTRACT MODEL</span></div><div v-if="state" class="ab-curve"><div class="ab-curve-labels"><span>{{number(state.basePrice)}} {{currency}}</span><span>{{number(state.terminalPrice)}} {{currency}}</span></div><svg viewBox="0 0 550 170" role="img" aria-label="Constant-product virtual reserve pricing model"><g class="ab-curve-grid"><path d="M20 35H530M20 90H530M20 145H530M20 25V150M145 25V150M270 25V150M395 25V150M530 25V150"/></g><path :d="`${curvePath} L530 150L20 150Z`" fill="var(--accent)" opacity=".15"/><path :d="curvePath" class="ab-curve-line"/><circle :cx="currentPoint.x" :cy="currentPoint.y" r="5" fill="var(--accent)" stroke="var(--ink)" stroke-width="3"/></svg><div class="ab-curve-axis"><span>0 tokens released</span><span>{{compact(allocation)}} curve allocation</span></div><p class="ab-curve-caption">Illustrative no-buyback path from {{number(state.phantom)}} {{currency}} in virtual reserves. Trades use live contract quotes. This is not a forecast or a pool price chart.</p></div></div>
        <div class="ab-progress-block"><div><span>Curve allocation completed</span><strong>{{(state?.progress||0).toFixed(3)}}%</strong></div><progress :value="state?.progress||0" max="100" aria-label="Curve allocation completed"></progress><p>{{state?.phase===2?'Liquidity is permanently locked in Uniswap v4.':state?.phase===1?'Curve reserves are held by the factory, awaiting pool creation.':`Reserve target: ${state?.target||'—'} ${currency}. The final buy can partially fill and refund.`}}</p></div>
        <div class="ab-activity-head"><h3>Recent curve activity</h3><span>5,000 BLOCKS · UP TO 100 TRADES</span></div><p v-if="activityError" class="ab-warn">{{activityError}}</p><div v-else-if="!records.length" class="activity-empty">{{loading?'Reading confirmed events…':'No curve trades in this block range.'}}</div><div v-else class="ab-activity-scroll"><table class="ab-activity-table"><thead><tr><th>Trade</th><th>Wallet</th><th>Tokens</th><th>{{currency}} paid / received</th><th>Proof</th></tr></thead><tbody><tr v-for="record in records" :key="`${record.hash}-${record.index}`"><td><span :class="record.side==='Buy'?'ab-buy-tag':'ab-sell-tag'">{{record.side}}</span></td><td>{{short(record.account)}}</td><td>{{compact(record.amount)}}</td><td>{{number(record.quote)}}</td><td><a :href="`${explorer}/tx/${record.hash}`" target="_blank" rel="noopener"><ArrowUpRight :size="13"/><span class="sr-only">View transaction</span></a></td></tr></tbody></table><p class="ab-curve-caption">Buys show total spent including fees. Sells show net received after fees. Pool swaps are outside this curve history.</p></div>
        <details v-if="metadata" class="ab-proof"><summary><ShieldCheck :size="14"/>Sound provenance<span>Stored onchain</span></summary><p>Published {{new Date(metadata.createdAt*1000).toLocaleDateString('en')}} · {{(metadata.audioBytes/1024).toFixed(1)}} KB</p><label>Audio hash</label><code>{{metadata.audioHash}}</code><p>Immutable bytes identify this sound; they do not certify copyright ownership.</p></details>
        <details v-if="state" class="ab-proof ab-creator-panel"><summary><ShieldCheck :size="14"/>Creator fees &amp; vesting<span>{{state.buybackEnabled?'Buyback enabled':'Direct fees'}}</span></summary><p>Fee recipient: <a :href="`${explorer}/address/${state.recipient}`" target="_blank" rel="noopener">{{short(state.recipient)}}</a>. {{100-state.protocolShareBps/100}}% of the base fee is allocated to the creator; extra creator tax goes entirely to that recipient.</p><div class="ab-creator-numbers"><span>Awaiting distribution<strong>{{number(state.pendingQuote)}} {{currency}}<br/>{{compact(state.pendingToken)}} {{symbol}}</strong></span><span>Your claimable fees<strong>{{number(state.claimableQuote)}} {{currency}}<br/>{{compact(state.claimableToken)}} {{symbol}}</strong></span></div><p v-if="state.needsOperator">A conversion or buyback is pending. The configured operator must process it before these fees become claimable.</p><button v-if="creatorConnected&&!state.needsOperator&&(Number(state.pendingQuote)>0||Number(state.pendingToken)>0)" class="ab-btn ab-btn-sm" :disabled="busy" @click="action(()=>distributeFees(address,pending),'Fees distributed to escrow. They are now available to claim.')">Distribute ready fees</button><div class="ab-creator-buttons"><button v-if="Number(state.claimableQuote)>0" class="ab-btn ab-btn-sm ab-btn-ghost" :disabled="busy" @click="action(()=>claimFees(state!.quote.address,pending),'Fees claimed to your wallet.')">Claim {{currency}} fees</button><button v-if="Number(state.claimableToken)>0" class="ab-btn ab-btn-sm ab-btn-ghost" :disabled="busy" @click="action(()=>claimFees(address,pending),'Vested tokens claimed to your wallet.')">Claim {{symbol}}</button></div><div class="ab-vesting"><strong>Sound buyback &amp; five-year vesting</strong><p>When enabled, {{state.buybackShareBps/100}}% of the creator base-fee allocation funds buybacks of this sound token. Additional creator tax is excluded. Bought tokens vest linearly over five years, with weighted deposit schedules. Releases split {{100-state.protocolShareBps/100}}% creator / {{state.protocolShareBps/100}}% protocol and must then be claimed from escrow.</p><div class="ab-creator-numbers"><span>Total deposited<strong>{{compact(state.vestLocked)}} {{symbol}}</strong></span><span>Releasable now<strong>{{compact(state.vestReleasable)}} {{symbol}}</strong></span></div><p>{{compact(state.vestReleased)}} tokens released so far. Buybacks reduce immediate creator cash and do not guarantee returns.</p><button v-if="state.canRelease&&Number(state.vestReleasable)>0" class="ab-btn ab-btn-sm" :disabled="busy" @click="action(()=>releaseVested(address,pending),'Vested tokens released to beneficiary escrow balances.')">Release vested tokens</button></div><div v-if="creatorConnected" class="creator-management"><button class="ab-btn ab-btn-sm" :disabled="busy||state.phase===1||state.phase===3" @click="action(()=>toggleBuyback(address,!state!.buybackEnabled,pending),'Buyback preference updated. Previously earmarked funds retain their existing treatment.')">{{state.buybackEnabled?'Disable future buybacks':'Enable future buybacks'}}</button><label>Transfer fee recipient<input v-model="newRecipient" :disabled="busy" placeholder="0x…" spellcheck="false"/></label><p>Future fees and unreleased vesting follow the new address. Already credited fees remain claimable by their current owner.</p><button class="ab-btn ab-btn-sm" :disabled="busy||!newRecipient" @click="action(()=>transferRecipient(address,newRecipient,pending),'Fee recipient transferred.')">Transfer recipient</button></div><p>Protocol administration can propose a recipient override with a 3-day delay and 3-day execution window. Internal conversions depend on the operator; view <a :href="`${explorer}/address/${state.operator}`" target="_blank" rel="noopener">operator address ↗</a>.</p></details>
      </div>
      <div class="ab-trade"><div class="ab-trade-title"><h3>Trade this sound.</h3><span>{{pool?'V4 POOL':`TEST ${currency}`}}</span></div>
        <div v-if="paused" class="ab-graduated"><strong>{{state?.phase===3?'Market rescued.':'Ready for the next stage.'}}</strong><p>{{state?.phase===3?'This market was rescued after failed graduation. Trading is closed. Review contract events for the reserve recipients.':'The curve is complete. Pool creation is a separate transaction anyone can submit. A failed pool attempt can be retried; swept reserves remain in the factory.'}}</p><button v-if="account&&state?.phase!==3" class="ab-btn ab-btn-hot ab-wide" :disabled="busy" @click="action(()=>graduateSound(address,pending),'Pool created. The liquidity position and surplus tokens are permanently locked.')">{{busy?'Creating pool…':'Complete graduation'}}<ArrowUpRight :size="16"/></button><button v-else-if="!account" class="ab-btn ab-btn-ghost ab-wide" @click="emit('connect')">Connect wallet</button></div>
        <template v-else><div v-if="pool" class="ab-dex-note"><Check :size="13"/>Locked liquidity · Continuing creator fees</div><div v-if="launchWindow" class="ab-snipe-note" role="status"><strong>Launch protection is active</strong><span>The opening tax starts at {{(state?.snipeStartBps||0)/100}}% before the fee cap and decays across {{state?.snipeSeconds}} seconds. Your quote includes your current tax. Creator and listed wallets are exempt. Wait for the window to end for ordinary pricing.</span></div><div class="ab-trade-tabs"><button :disabled="busy" :class="{'is-on':side==='buy'}" @click="side='buy'">Buy</button><button :disabled="busy" :class="{'is-on':side==='sell'}" @click="side='sell'">Sell</button></div><label class="ab-trade-amount">{{side==='buy'?'Amount to spend':'Token amount'}}<span>{{side==='buy'?currency:symbol}}</span><input v-model="amount" :disabled="busy" inputmode="decimal" placeholder="0"/></label><div class="ab-shortcuts"><button v-for="preset in side==='buy'?(currency==='ETH'?['0.001','0.01','0.1']:['1','10','100']):['10000','100000','1000000']" :key="preset" :disabled="busy" @click="amount=preset">{{Number(preset)<1?number(preset):compact(preset)}}</button><button v-if="side==='sell'" :disabled="busy" @click="amount=state?.balance||'0'">Max</button></div>
        <div class="ab-quote"><span>Estimated output<strong>{{quoting?'Getting quote…':quoted?`${number(formatUnits(quoted.output,quoted.outputDecimals))} ${side==='buy'?symbol:currency}`:'—'}}</strong></span><span>Base fee (included)<strong>{{baseFee/100}}%{{quoted&&!pool?` · ${number(formatUnits(quoted.baseFee,quoted.feeDecimals))} ${currency}`:''}}</strong></span><span>Creator tax (included)<strong>{{(state?.taxBps||0)/100}}%{{quoted&&!pool?` · ${number(formatUnits(quoted.creatorTax,quoted.feeDecimals))} ${currency}`:''}}</strong></span><span v-if="quoted&&quoted.snipeTax>0n">Opening tax (included)<strong>{{number(formatUnits(quoted.snipeTax,quoted.feeDecimals))}} {{currency}}</strong></span><span v-if="quoted&&quoted.refund>0n">Estimated immediate refund<strong>{{number(formatUnits(quoted.refund,quoted.feeDecimals))}} {{currency}}</strong></span><span>Price tolerance<strong>1%</strong></span><span>Your tokens<strong>{{compact(state?.balance||'0')}} {{symbol}}</strong></span><span>Your market currency<strong>{{number(state?.quoteBalance||'0')}} {{currency}}</strong></span></div><p v-if="quoted&&quoted.refund>0n" class="ab-fine">Partial fill: the price limit scales with actual spend. The remaining payment returns directly to your wallet.</p><p v-if="quoteError" class="ab-warn">{{quoteError}}</p><button v-if="!account" class="ab-btn ab-btn-ghost ab-wide" @click="emit('connect')">Connect wallet<Wallet :size="16"/></button><button v-else class="ab-btn ab-btn-hot ab-wide" :disabled="busy||quoting||!quoted||loading" @click="execute"><LoaderCircle v-if="busy" :size="17" class="is-spin"/>{{busy?'Confirming…':wrongNetwork?'Switch network & continue':`${side==='buy'?'Buy':'Sell'} ${symbol}`}}<ArrowUpRight v-if="!busy" :size="17"/></button></template>
        <p v-if="state" class="trade-fee-note">Base-fee allocation: <strong>{{100-state.protocolShareBps/100}}% creator + {{state.protocolShareBps/100}}% protocol.</strong> Additional creator tax is separate. {{pool?'Hook fees are deducted from swap output. The quote includes them.':'Buy fees are deducted from your spend. Sell fees are deducted from proceeds.'}} {{state.buybackEnabled?'Buybacks use part of the creator base-fee allocation.':''}}</p><p class="ab-fine">Outputs and refunds go directly to your wallet. Network gas is separate. Test assets have no monetary value. No guaranteed returns.</p><div v-if="pool&&state" class="ab-pool-proof"><span>Locked position #{{state.positionId}}</span><button @click="copy(state.poolId,'pool')">{{copied==='pool'?'Copied':'Copy pool ID'}}</button></div><p v-if="pool&&state" class="ab-fine">{{compact(state.lockedSurplus)}} surplus sound tokens permanently locked.</p><div v-if="message" class="ab-sheet-msg" role="status">{{message}}</div><a v-if="txHash" class="ab-tx" :href="`${explorer}/tx/${txHash}`" target="_blank" rel="noopener">View transaction<ExternalLink :size="12"/></a>
      </div>
    </div>
  </section>
</template>

